const P=window.PRODUCTS,$=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],page=document.body.dataset.page,params=new URLSearchParams(location.search),money=n=>'₹'+n.toLocaleString('en-IN'),url=p=>'product.html?id='+p.id;
const icons={search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 6 6"/>',bag:'<path d="M5 7h14l1 15H4L5 7Zm3 0V5a4 4 0 0 1 8 0v2"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>'};const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[k]}</svg>`;
