function visual(p,back=false){return p.asset<6?`<div class="texture slot-${p.asset} ${back?'reverse':''}" style="--slot:${p.asset}" role="img" aria-label="${p.name}, ${back?'back':'front'} view"></div>`:`<img class="photo-texture" loading="lazy" src="assets/garment${p.asset-5}_${back?'back':'front'}.png" alt="${p.name}, ${back?'back':'front'} view">`}
