function home(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">SHADES STUDIO / COLLECTION IN MOTION</span><h1>Designed<br>for Motion.<br><em>Built for<br>Presence.</em></h1><p>Contemporary menswear engineered<br>for the way you move.</p><div class="actions"><a class="button dark" href="shop.html">Explore collection</a><a class="text-link" href="lookbook.html">View lookbook</a></div><span class="hero-note">SIX SILHOUETTES. EVERY ANGLE.</span></div><div class="showroom"><div class="stage-heading"><span>THE LIVING WARDROBE</span><span>COIMBATORE / INDIA</span></div><div class="stage-type" aria-hidden="true">IN GOOD FORM.</div><div class="rack-viewport"><div class="metal-rail"></div><div id="rack" class="rack">${P.slice(0,6).map((p,i)=>`<button class="hanger" data-hanger="${i}" aria-label="Explore ${p.name}" aria-pressed="false"><div class="suspension"></div>${solid(p)}<span class="hanger-label">${p.category}</span></button>`).join('')}</div></div><div class="stage-instructions"><span>HOVER OR TAP TO BRING A PIECE FORWARD</span><span>FRONT + BACK</span></div><div id="hero-details" class="hero-details" aria-live="polite"><div><span class="eyebrow">YOUR WARDROBE, IN PERSPECTIVE</span><h3>Find a different side of you.</h3><p>Select a hanging piece to explore its details.</p></div></div></div></section><div class="motion-strip"><div>FORM &nbsp; / &nbsp; TEXTURE &nbsp; / &nbsp; MOVEMENT &nbsp; / &nbsp; A DIFFERENT SHADE OF YOU &nbsp; / &nbsp; FORM &nbsp; / &nbsp; TEXTURE &nbsp; / &nbsp; MOVEMENT &nbsp; / &nbsp; A DIFFERENT SHADE OF YOU &nbsp; / &nbsp;</div></div><section class="section"><div class="section-head"><div><span class="eyebrow">NEW PERSPECTIVES</span><h2>Good form.<br>Great everyday.</h2></div><a href="shop.html" class="text-link">Discover all ${P.length} pieces</a></div><div class="products home-products">${[P[0],P[1],P[7],P[11]].map(card).join('')}</div></section><section class="campaign"><div><span class="eyebrow">THE SHADES EDIT</span><h2>Less trying.<br><em>More being you.</em></h2><p>The art of getting dressed, without overthinking it.</p><a class="button cream" href="lookbook.html">Step inside the lookbook</a></div><div class="campaign-art">${visual(P[0])}<span>EVERYDAY, REDEFINED.</span></div></section>${newsletter()}`}
function shop(){return `<section class="section page-intro"><span class="eyebrow">THE CONSIDERED WARDROBE</span><h1>Find your <em>next everyday.</em></h1><p>Explore ${P.length} sample menswear styles, from quiet essentials to layers with presence.</p></section><section class="section shop-section"><div class="shop-tools"><div id="filters" class="filters"></div><div class="catalog-tools"><input id="search" type="search" placeholder="Search the collection" aria-label="Search collection"><select id="sort" aria-label="Sort products"><option value="featured">Featured</option><option value="new">Newest styles</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select></div></div><p id="results-count" class="muted"></p><div id="products" class="products"></div><p class="sample-note">Sample styles, prices, fabric descriptions and sizing. Generated studio imagery illustrates the collection; six additional style studies share their reference silhouette.</p></section>`}
function product(){let p=P.find(p=>p.id===params.get('id'));if(!p){document.title='Product not found — SHADES';return `<section class="section empty"><h1>This piece isn't here.</h1><p>Discover your next favourite in the collection.</p><a class="button dark" href="shop.html">Explore collection</a></section>`}document.title=p.name+' — SHADES';return `<section class="product-page section"><div class="breadcrumbs"><a href="shop.html">Collection</a> / <a href="shop.html?category=${p.category}">${p.category}</a> / ${p.name}</div><div class="product-layout"><div><div class="product-stage" id="product-stage"><div class="viewer" id="viewer">${solid(p)}</div><span class="viewer-caption">TWO VIEWS. ONE CONSIDERED PIECE.</span></div><div class="view-controls"><button data-view="front" class="active" aria-pressed="true">Front view</button><button data-view="back" aria-pressed="false">Back view</button><button id="rotate-product">Rotate 360°</button></div><p class="sample-note">Rotate between front and back views. ${p.note}</p></div><div class="product-info"><span class="eyebrow">${p.category.toUpperCase()} / ${p.sku}</span><h1>${p.name}</h1><span class="product-price">${money(p.price)}</span><p>${p.description}</p><div class="color-choice"><span class="color-dot color-${p.asset}"></span>${p.color}</div><form id="add-form"><div class="size-heading"><label for="size">Choose your size</label><button type="button" class="text-link" id="guide-open">Size guide</button></div><div class="size-buttons">${p.sizes.map(s=>`<label><input type="radio" name="size" value="${s}" required><span>${s}</span></label>`).join('')}</div><div class="add-row"><label class="qty-label">Qty <input type="number" id="quantity" min="1" max="10" value="1" required></label><button class="button dark" id="add-button">Add to bag <span>＋</span></button></div><p id="add-status" role="status"></p></form><div class="product-accordions"><details open><summary>Fabric & details</summary><p>${p.fabric}. ${p.fit} fit. Color: ${p.color}. Sample specifications for this concept catalog.</p></details><details><summary>Fit & sizing</summary><p>${p.fit} silhouette. Choose your usual size for the intended fit. Use the body measurement guide as an illustration; final garment measurements are not yet supplied.</p></details><details><summary>Care</summary><p>${p.care}</p></details><details><summary>Delivery & returns</summary><p>This is a sample showroom. Delivery charges, dispatch times, service areas and return terms will be confirmed by SHADES before ordering opens.</p></details></div></div></div></section><section class="section related"><div class="section-head"><div><span class="eyebrow">GOOD COMPANY</span><h2>Complete your rotation.</h2></div><a class="text-link" href="shop.html">View all pieces</a></div><div class="products">${P.filter(x=>x.id!==p.id).slice(0,4).map(card).join('')}</div></section>`}
