function runway(){return `<section class="runway-shell" aria-label="Fashion Runway"><div class="runway-stage" id="runway-stage" tabindex="0" role="region" aria-label="Menswear runway. Drag horizontally, scroll here, or use arrow keys to explore six looks." aria-describedby="runway-instructions"><div class="runway-intro"><span class="eyebrow">SHADES / FASHION RUNWAY</span><h1>Presence, <em>in motion.</em></h1><p id="look-description"></p></div><div class="runway-line" id="runway-line"></div><div class="runway-caption"><span>THE CONSIDERED WARDROBE</span><h2 id="look-title"></h2></div><div class="runway-controls"><button id="runway-prev" aria-label="Previous look"><svg viewBox="0 0 24 24"><path d="m14 6-6 6 6 6"/></svg></button><span class="runway-count" id="look-count"></span><button id="runway-next" aria-label="Next look"><svg viewBox="0 0 24 24"><path d="m10 6 6 6-6 6"/></svg></button></div></div><aside class="runway-rail" id="runway-rail" aria-label="Pieces in the selected look"></aside></section><div class="runway-help"><p id="runway-instructions">Drag to explore. Or use the controls and arrow keys.</p><div class="runway-dots" id="runway-dots" aria-label="Choose a runway look"></div><a class="text-link" href="shop.html">Explore the collection</a></div><p class="sr-only" role="status" id="look-announcement"></p>`}
