if(page==='home'&&!window.initShadesHero){
 let selected=-1,back=false;const buttons=all('[data-hanger]');function select(i){if(selected===i)return;selected=i;back=false;$('#rack').classList.add('has-selection');buttons.forEach((b,j)=>{b.classList.toggle('selected',j===i);b.classList.remove('turned');b.setAttribute('aria-pressed',String(j===i))});const p=P[i];$('#hero-details').innerHTML=`<div><span class="eyebrow">${p.category} / ${p.color}</span><h3>${p.name}</h3><p>${p.fit} fit · ${p.fabric} · S–XXL</p></div><div class="hero-detail-actions"><span>${money(p.price)}</span><button class="turn-button" id="turn-garment" aria-label="Show back of garment">Show back</button><a class="button cream" href="${url(p)}">View product</a></div>`;$('#turn-garment').onclick=()=>{back=!back;buttons[i].classList.toggle('turned',back);$('#turn-garment').textContent=back?'Show front':'Show back';$('#turn-garment').setAttribute('aria-label',back?'Show front of garment':'Show back of garment')};}
 buttons.forEach((b,i)=>{b.onpointerenter=e=>{if(e.pointerType==='mouse')select(i)};b.onfocus=()=>select(i);b.onclick=()=>select(i)});$('#rack').addEventListener('pointermove',e=>{if(e.pointerType!=='mouse'||selected<0)return;const b=buttons[selected],r=b.getBoundingClientRect();b.style.setProperty('--lean',Math.max(-8,Math.min(8,(e.clientX-r.left-r.width/2)/r.width*10))+'deg')});
}
if(page==='shop'){
 let filter=params.get('category')||'All',query=params.get('search')||'',sort=params.get('sort')||'featured';const cats=['All',...new Set(P.map(p=>p.category))];if(!cats.includes(filter))filter='All';$('#filters').innerHTML=cats.map(c=>`<button data-category="${c}" class="${filter===c?'active':''}" aria-pressed="${filter===c}">${c}</button>`).join('');$('#search').value=query;$('#sort').value=['featured','new','low','high'].includes(sort)?sort:'featured';function render(){let ps=P.filter(p=>(filter==='All'||p.category===filter)&&`${p.name} ${p.color} ${p.fabric}`.toLowerCase().includes(query.toLowerCase()));if(sort==='low')ps.sort((a,b)=>a.price-b.price);if(sort==='high')ps.sort((a,b)=>b.price-a.price);if(sort==='new')ps.reverse();$('#products').innerHTML=ps.length?ps.map(card).join(''):'<p class="empty-results">No pieces match this selection. Try another search or category.</p>';$('#results-count').textContent=`${ps.length} pieces in this edit`;const u=new URL(location.href);u.searchParams.set('category',filter);u.searchParams.set('search',query);u.searchParams.set('sort',sort);history.replaceState(null,'',u)}all('[data-category]').forEach(b=>b.onclick=()=>{filter=b.dataset.category;all('[data-category]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});render()});$('#search').oninput=e=>{query=e.target.value;render()};$('#sort').onchange=e=>{sort=e.target.value;render()};render();if(params.has('search'))$('#search').focus({preventScroll:true});
}
const reduce=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
async function foldToBag(p){if(reduce())return;const source=$('#product-stage'),r=source.getBoundingClientRect(),target=$('#bag-icon').getBoundingClientRect();const ghost=document.createElement('div');ghost.className='fold-ghost';ghost.style.cssText=`left:${r.left+r.width/2-90}px;top:${r.top+r.height/2-130}px;width:180px;height:260px;`;ghost.innerHTML=`<div class="fold-left">${visual(p)}</div><div class="fold-center">${visual(p)}</div><div class="fold-right">${visual(p)}</div>`;document.body.append(ghost);await Promise.all([ghost.querySelector('.fold-left').animate([{transform:'rotateY(0)'},{transform:'rotateY(165deg)'}],{duration:380,easing:'ease-in-out',fill:'forwards'}).finished,ghost.querySelector('.fold-right').animate([{transform:'rotateY(0)'},{transform:'rotateY(-165deg)'}],{duration:380,easing:'ease-in-out',fill:'forwards'}).finished]);const initialX=r.left+r.width/2-90,initialY=r.top+r.height/2-130;const dx=target.left+target.width/2-initialX-90,dy=target.top+target.height/2-initialY-130;await ghost.animate([{transform:'translate(0,0) scale(1) rotateX(0)',opacity:1},{offset:.4,transform:`translate(${dx*.35}px,${Math.min(dy,-160)}px) scale(.55) rotateX(55deg) rotateZ(-12deg)`,opacity:1},{transform:`translate(${dx}px,${dy}px) scale(.06) rotateX(70deg) rotateZ(15deg)`,opacity:0}],{duration:750,easing:'cubic-bezier(.4,0,.4,1)',fill:'forwards'}).finished;ghost.remove();$('#bag-icon').animate([{transform:'scale(1)'},{transform:'scale(1.3) rotate(-8deg)'},{transform:'scale(1)'}],{duration:380})}
